Generated Query:
PREFIX ins: <http://data.world/schema/insurance/>

SELECT ?policyNumber (COUNT(DISTINCT ?claim) AS ?claimCount)
WHERE {
  SERVICE <mapped> {
    ?claim a ins:Claim ;
           ins:against ?coverage .
    ?coverage ins:hasPolicy ?policy .
    ?policy ins:policyNumber ?policyNumber .
  }
}
GROUP BY ?policyNumber
ORDER BY ?policyNumber

PREFIX ins: <http://data.world/schema/insurance/>

SELECT ?policyNumber (SUM(?amount) AS ?totalPremiumAmount)
WHERE {
  SERVICE <mapped> {
    ?coverage a ins:PolicyCoverageDetail ;
              ins:hasPolicy ?policy ;
              ins:hasPremiumAmount ?premium .
    ?policy ins:policyNumber ?policyNumber .
    ?premium ins:premiumAmount ?amount .
  }
}
GROUP BY ?policyNumber

PREFIX ins: <http://data.world/schema/insurance/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?claimNumber
       (COALESCE(SUM(xsd:decimal(?lossPaymentAmount)), 0) + COALESCE(SUM(xsd:decimal(?lossReserveAmount)), 0) AS ?totalLossAmount)
WHERE {
  SERVICE <mapped> {
    ?claim a ins:Claim ;
           ins:claimNumber ?claimNumber .

    OPTIONAL {
      ?claim ins:hasLossPayment ?lossPayment .
      ?lossPayment ins:lossPaymentAmount ?lossPaymentAmount .
    }

    OPTIONAL {
      ?claim ins:hasLossReserve ?lossReserve .
      ?lossReserve ins:lossReserveAmount ?lossReserveAmount .
    }
  }
}
GROUP BY ?claimNumber

PREFIX ins: <http://data.world/schema/insurance/>

SELECT DISTINCT ?policyHolder ?premium
WHERE {
  SERVICE <mapped> {
    ?policy ins:hasPolicyHolder ?policyHolder ;
            ins:hasPolicy ?coverage .
    ?coverage ins:hasPremiumAmount ?premium .
  }
}

PREFIX ins: <http://data.world/schema/insurance/>

SELECT ?claimNumber ?lossPaymentAmount ?lossReserveAmount ?expensePaymentAmount ?expenseReserveAmount
WHERE {
  SERVICE <mapped> {
    ?claim a ins:Claim ;
           ins:claimNumber ?claimNumber .

    OPTIONAL {
      ?claim ins:hasLossPayment ?lossPayment .
      ?lossPayment ins:lossPaymentAmount ?lossPaymentAmount .
    }

    OPTIONAL {
      ?claim ins:hasLossReserve ?lossReserve .
      ?lossReserve ins:lossReserveAmount ?lossReserveAmount .
    }

    OPTIONAL {
      ?claim ins:hasExpensePayment ?expensePayment .
      ?expensePayment ins:expensePaymentAmount ?expensePaymentAmount .
    }

    OPTIONAL {
      ?claim ins:hasExpenseReserve ?expenseReserve .
      ?expenseReserve ins:expenseReserveAmount ?expenseReserveAmount .
    }
  }
}
